#!/usr/bin/env python3
"""Build encyclopedic Reminiscencia zone and tileset records from proof manifests."""
from __future__ import annotations
import argparse,json,shutil
from pathlib import Path
from inventory_relict import sha256_file,write_json
def load(p):return json.loads(p.read_text())
def build(game):
 game=game.resolve();cand=game/"conversion/pmdo_candidates";cr=load(cand/"conversion_report.json");static=load(game/"conversion/pmdo_renders/manifest.json");vfx=load(game/"vfx/manifest.json");source=load(game/"metadata/source_archive.json");sb={x["map_id"]:x for x in static["renders"]};cb={x["map_id"]:x for x in cr["maps"]};tb={x["map_id"]:x for x in vfx["timelines"]};runtime={int(p.parent.name.split("_")[1]) for p in (cand/"runtime").glob("map_*/runtime_report.json")};expected=set(range(1,553))
 if set(sb)!=expected or set(cb)!=expected or set(tb)!=expected:raise ValueError("catalog coverage")
 for root in (game/"zones",game/"tilesets",game/"manifests"):shutil.rmtree(root,ignore_errors=True);root.mkdir(parents=True)
 zones=[]
 for mid in range(1,553):
  s=sb[mid];c=cb[mid];t=tb[mid];side=load(cand/c["sidecar"]);runtime_path=cand/f"runtime/map_{mid:03d}/runtime_report.json"
  data={"schema_version":"1.0.0","game_id":"reminiscencia","map_id":mid,"source_identity":{"name":s["source_name"],"source_order":s["source_order"],"tileset_id":s["tileset_id"],"tileset_name":s["tileset_name"]},"status":c["status"],"geometry":{"source_tiles":[s["width_tiles"],s["height_tiles"]],"source_pixels":[s["width_px"],s["height_px"]],"source_tile_size_px":32,"pmdo_pixels":c["pmdo_dimensions_px"],"pmdo_tile_size_px":16,"pmdo_collision_size_px":8,"pmdo_tex_size":2,"default_viewport_px":[320,240],"default_viewport_exact_fit":c["default_viewport_exact_fit"],"edge_view":"Clamp"},"layers_and_visuals":{"source_tile_layer_count":s["layer_count"],"panorama_converted":c["panorama_converted"],"fog_name":c["fog_name"],"fog_materialized":c["fog_materialized"],"environmental_tile_event_count":s["environmental_tile_event_count"],"environment_sprite_entity_count":c["environment_sprite_entity_count"],"environment_sprite_page_context_count":c["environment_sprite_page_context_count"],"missing_tile_ids":c["missing_tile_ids"],"unresolved_dependencies":c["unresolved_dependencies"],"excluded_visual_scene":s["excluded_visual_scene"]},"collision":{"partial_direction_masks":c["partial_direction_masks"],"native_policy":side["partial_collision_policy"],"exact_mask_in_sidecar":True},"entities":{"source_event_count":side["entities"]["source_event_count"],"page_placement_count":side["entities"]["page_placement_count"],"identities_redacted":True,"casting_pixels_exported":False},"artifacts":{"ground_bundle":"conversion/pmdo_candidates/"+cr["ground_storage"]["file"],"ground_member":c["ground"],"ground_sha256":c["ground_sha256"],"sidecar":"conversion/pmdo_candidates/"+c["sidecar"],"sidecar_sha256":c["sidecar_sha256"],"preview":"conversion/pmdo_candidates/"+c["preview"],"preview_sha256":c["preview_sha256"],"source_render":"conversion/pmdo_renders/"+s["file"],"source_render_sha256":s["sha256"],"visual_timeline":t["file"],"visual_timeline_sha256":t["sha256"],"runtime_report":f"conversion/pmdo_candidates/runtime/map_{mid:03d}/runtime_report.json" if mid in runtime else None,"runtime_report_sha256":sha256_file(runtime_path) if mid in runtime else None},"provenance":{"source_archive_sha256":source["verified_sha256"],"source_repository_commit":source["source_commit"],"conversion_scale":[1,2]}}
  path=game/"zones"/f"map_{mid:03d}.json";write_json(path,data);zones.append({"map_id":mid,"status":c["status"],"file":path.relative_to(game).as_posix(),"sha256":sha256_file(path)})
 source_ts={}
 for x in static["renders"]:source_ts.setdefault(x["tileset_id"],{"source_name":x["tileset_name"],"map_ids":[]})["map_ids"].append(x["map_id"])
 tiles=[]
 for a in cr["atlases"]:
  i=a["tileset_id"];data={"schema_version":"1.0.0","game_id":"reminiscencia","tileset_id":i,"source_name":source_ts[i]["source_name"],"map_ids":sorted(source_ts[i]["map_ids"]),"pmdo":{"sheet":a["sheet"],"file":a["file"],"sha256":a["sha256"],"size_bytes":a["size_bytes"],"tile_size_px":16,"atlas_payload_count":a["atlas_payload_count"],"used_tile_id_count":a["used_tile_id_count"],"environment_sprite_sheet_count":a["environment_sprite_sheet_count"],"environment_sprite_payload_count":a["environment_sprite_payload_count"],"panorama_source_name":a["panorama_source_name"],"fog_source_name":a["fog_source_name"],"fog_frame_count":a["fog_frame_count"]},"missing_tile_ids":a["missing_tile_ids"],"unresolved_dependencies":a["unresolved_dependencies"]};path=game/"tilesets"/f"tileset_{i:03d}.json";write_json(path,data);tiles.append({"tileset_id":i,"file":path.relative_to(game).as_posix(),"sha256":sha256_file(path)})
 manifest={"schema_version":"1.0.0","result":"REMINISCENCIA_ENCYCLOPEDIC_CATALOG_PASS","game_id":"reminiscencia","map_count":552,"tileset_count":len(tiles),"status_counts":cr["status_counts"],"runtime_validated_map_ids":sorted(runtime),"zones":zones,"tilesets":tiles,"authorities":{"candidate_report":{"file":"conversion/pmdo_candidates/conversion_report.json","sha256":sha256_file(cand/"conversion_report.json")},"vfx_manifest":{"file":"vfx/manifest.json","sha256":sha256_file(game/"vfx/manifest.json")},"animations_manifest":{"file":"animations/manifest.json","sha256":sha256_file(game/"animations/manifest.json")}}};write_json(game/"manifests/pmdo_catalog.json",manifest)
 (game/"previews").mkdir(exist_ok=True);(game/"previews/README.md").write_text("# Previews\n\nLes 552 previews sont sous `conversion/pmdo_candidates/`.\n");(game/"reports").mkdir(exist_ok=True);(game/"reports/README.md").write_text("# Rapports\n\nVoir `../../../reports/REMINISCENCIA_PMDO_CONVERSION.md`.\n");return manifest
def main():
 p=argparse.ArgumentParser();p.add_argument("--game-root",type=Path,required=True);a=p.parse_args();m=build(a.game_root);print(json.dumps({"result":m["result"],"map_count":m["map_count"],"tileset_count":m["tileset_count"],"runtime_validated_map_ids":m["runtime_validated_map_ids"]},sort_keys=True));return 0
if __name__=="__main__":raise SystemExit(main())
